  if key.startswith(('ZS_','OPENAI_','ANTHROPIC_','OPENROUTER_','MINI_AGENT_INTERNAL_')) or key.endswith(('_API_KEY','_AUTH_TOKEN')):env.pop(key,None)
 for key in ('ZS_CONFIG_DIR','ZS_DATA_DIR','ZS_LOCAL_DATA_DIR','ZS_STATE_DIR','ZS_CACHE_DIR','ZS_CREDENTIALS_DIR'):
  path=root/key;path.mkdir(mode=0o700);env[key]=str(path)
